/* logos.js — CBVI Revisiones Técnicas
   Logos institucionales embebidos en base64. Van DENTRO del archivo para que
   siempre carguen: en la interfaz, en el PDF del certificado y sin conexión.
   Antes se usaba <img src="logo.png"> y fallaba cuando la ruta no resolvía.
   NO borrar ni renombrar: index.html y verificar.html dependen de este archivo. */
(function(g){
  "use strict";
  var L={
    cbvi:"data:image/png;base64,",
    cbviPdf:"data:image/jpeg;base64,",
    lema:"ABNEGACI\u00d3N Y DISCIPLINA",
    institucion:"CUERPO DE BOMBEROS VOLUNTARIOS DE IN\u00cdRIDA",
    ciudad:"In\u00edrida, Guain\u00eda \u2014 Colombia"
  };
  g.LOGOS=L;
  function pintar(){var n=document.querySelectorAll("img[data-logo]");for(var i=0;i<n.length;i++){n[i].src=L.cbvi;}}
  if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",pintar);else pintar();
  g.pintarLogos=pintar;
})(typeof window!=="undefined"?window:this);
